    toggleLoadout(type){if(!this.availableTypes().includes(type)){this.message=`${this.tr(type)} · ${this.tr('lockedMessage')}`;return false;}if(this.loadout.includes(type)){if(this.loadout.length===1){this.message=this.tr('keepOne');return false;}return this.setLoadout(this.loadout.filter(item=>item!==type));}if(this.loadout.length>=5){this.message=this.tr('loadoutFull');return false;}return this.setLoadout([...this.loadout,type]);}
    tr(key){const language=this.options.language?.()||'de';return tdFusionName(key,language)||TOWER_COPY[language]?.[key]||TOWER_COPY.de[key]||key;}
    setMap(id){const map=TD_MAPS.find(item=>item.id===id)||TD_MAPS[0];this.map=map;this.mapId=map.id;this.path=map.path;this.spots=map.spots;this.pathMeasure=tdMeasure(this.path);this.pathLength=this.pathMeasure.total;return map;}
    sound(n){try{this.options.onSound?.(n);}catch{}}
    start(){const challenge=TD_CHALLENGES.find(c=>c.id===this.challengeId)||TD_CHALLENGES[0];this.phase='playing';this.loadout=this.cleanLoadout(this.loadout);this.selectedType=this.loadout[0]||'archer';this.selectedTower=null;this.morphSelection=[];this.fusionTypesUsed.clear();this.towers=[];this.enemies=[];this.projectiles=[];this.effects=[];this.particles=[];this.wave=0;this.maxWaves=this.endless?Infinity:12;this.waveActive=false;this.waveCooldown=1.1;this.spawnQueue=[];this.spawnTimer=0;this.gold=challenge.gold;this.lives=challenge.lives;this.startingLives=challenge.lives;this.score=0;this.kills=0;this.built=0;this.upgrades=0;this.sold=0;this.bosses=0;this.morphs=0;this.maxGold=challenge.gold;this.maxTowerTypes=0;this.specialHits=0;this.time=0;this.message=this.endless?this.tr('endlessReady'):this.tr('readyMessage');this.reported=false;this.sound('tower_start');}
    setChallenge(id){if(!TD_CHALLENGES.some(c=>c.id===id))return false;this.challengeId=id;return true;}
    selectType(type){if(this.loadout.includes(type)){if(this.morphSelection.length)this.cancelMorph();this.selectedType=type;this.selectedTower=null;this.sound('tower_select');}}
    startWave(){if(this.phase!=='playing'||this.waveActive||this.wave>=this.maxWaves)return false;this.wave++;this.waveActive=true;this.spawnQueue=tdWave(this.wave);if(this.challengeId==='boss_rush'&&this.wave%4===0)this.spawnQueue.push('boss');this.spawnTimer=0;this.waveCooldown=0;this.message=`${this.endless?this.tr('endlessWaveMessage'):this.tr('waveMessage')} ${this.wave}`;this.sound('tower_wave');return true;}
    spotAt(x,y){let best=null,dist=Infinity;for(const spot of this.spots){const d=Math.hypot(x-spot.x,y-spot.y);if(d<dist){best=spot;dist=d;}}return dist<=34?best:null;}
